#!/usr/bin/env python3
"""Offline cloud activation plan only; no network, subprocess, credentials or mutations."""
import argparse,json,uuid
p=argparse.ArgumentParser();p.add_argument('--organization',required=True);p.add_argument('--site',required=True);p.add_argument('--gateway',required=True);p.add_argument('--connection');a=p.parse_args()
for v in [a.organization,a.site,a.gateway]+([a.connection]if a.connection else[]):assert str(uuid.UUID(v))==v and uuid.UUID(v).int
root='/api/v1/organizations/'+a.organization
steps=[{'method':'GET','path':root+'/ipsec/settings','require':'normal organization opt-in; preserve current settings'}, {'method':'GET','path':root+'/sites/'+a.site,'require':'site belongs to organization and gateway bound'}, {'method':'GET','path':root+'/sites/'+a.site+'/subnets','require':'exact approved customer LAN with independently proved physical reachability'}, {'method':'GET','path':root+'/nodes/'+a.gateway,'require':'real enrolled active current certificate and heartbeat; no injected capability'}, {'method':'GET','path':root+'/ipsec/eligibility?site_id='+a.site+'&gateway_node_id='+a.gateway,'require':'eligible=true and bgp.eligible=true after actual native factory qualification'}, {'method':'GET','path':root+'/zero-trust-mode','require':'enforcing'}, {'method':'POST','path':root+'/ipsec/configuration-check','require':'privately assembled actual AWS config; never print PSKs; root executes separately'}, {'method':'POST','path':root+'/ipsec/connections','require':'distinct disabled provider; persist generated UUIDs before send; normal auth/CSRF only'}]
if a.connection:steps += [{'method':'GET','path':root+'/ipsec/connections/'+a.connection+'/configuration','require':'secret-free exact approved profile/ASNs/insidepairs'}, {'method':'PUT','path':root+'/ipsec/connections/'+a.connection+'/intent','require':'root-owned normal CAS enable only after fresh eligibility/native proof; use actual desired revision'}, {'method':'GET','path':root+'/ipsec/connections/'+a.connection+'/status','require':'two genuine IPsec/BGP sessions; exact route/counter evidence separate'}]
print(json.dumps({'execution_performed':False,'owner':'root executes deployment/activation separately','aws_cli_host':'ubuntu@16.170.207.192 only','steps':steps},indent=2))
